// Technical indicators per ticker. Emits rows for the last days_back sessions.
const ctx = $('When called').first().json;
const daysBack = Number(ctx.days_back || 5);
const byT = {};
for (const it of $input.all()) { const r = it.json; (byT[r.ticker] ||= []).push(r); }

const sma = (a, i, n) => i + 1 < n ? null : a.slice(i - n + 1, i + 1).reduce((s, v) => s + v, 0) / n;
const std = (arr) => { const m = arr.reduce((s, v) => s + v, 0) / arr.length; return Math.sqrt(arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length); };
const r4 = (v) => v == null || !isFinite(v) ? null : Math.round(v * 10000) / 10000;

const rows = [];
for (const [ticker, hist] of Object.entries(byT)) {
  const closes = hist.map(h => h.close), highs = hist.map(h => h.high), lows = hist.map(h => h.low), vols = hist.map(h => h.volume);
  const n = hist.length;
  // Wilder RSI14 and ATR14, computed incrementally
  const rsi = new Array(n).fill(null), atr = new Array(n).fill(null);
  let ag = 0, al = 0, atrv = 0;
  for (let i = 1; i < n; i++) {
    const ch = closes[i] - closes[i - 1];
    const g = Math.max(ch, 0), l = Math.max(-ch, 0);
    const tr = Math.max(highs[i] - lows[i], Math.abs(highs[i] - closes[i - 1]), Math.abs(lows[i] - closes[i - 1]));
    if (i <= 14) { ag += g / 14; al += l / 14; atrv += tr / 14; if (i === 14) { rsi[i] = al === 0 ? 100 : 100 - 100 / (1 + ag / al); atr[i] = atrv; } }
    else { ag = (ag * 13 + g) / 14; al = (al * 13 + l) / 14; atrv = (atrv * 13 + tr) / 14; rsi[i] = al === 0 ? 100 : 100 - 100 / (1 + ag / al); atr[i] = atrv; }
  }
  const start = Math.max(0, n - daysBack);
  for (let i = start; i < n; i++) {
    const w252 = hist.slice(Math.max(0, i - 251), i + 1);
    const hi = Math.max(...w252.map(h => h.high)), lo = Math.min(...w252.map(h => h.low));
    let volz = null;
    if (i >= 20) { const prev = vols.slice(i - 20, i); const m = prev.reduce((s, v) => s + v, 0) / 20; const sd = std(prev); volz = sd > 0 ? (vols[i] - m) / sd : 0; }
    rows.push({
      ticker, as_of: hist[i].as_of,
      sma20: r4(sma(closes, i, 20)), sma50: r4(sma(closes, i, 50)), sma200: r4(sma(closes, i, 200)),
      rsi14: r4(rsi[i]), atr14: r4(atr[i]), vol_z20: r4(volz),
      hi52w: r4(hi), lo52w: r4(lo), pct_from_hi52w: r4((closes[i] - hi) / hi),
      ret_1d: i >= 1 ? r4(closes[i] / closes[i - 1] - 1) : null,
      ret_5d: i >= 5 ? r4(closes[i] / closes[i - 5] - 1) : null,
      ret_20d: i >= 20 ? r4(closes[i] / closes[i - 20] - 1) : null,
    });
  }
}
return [{ json: { run_id: ctx.run_id, rows, count: rows.length, tickers: Object.keys(byT).length } }];
